/* ---------- deterministic natural map generator ---------- */
function hashSeed(s){let h=2166136261>>>0;for(const c of String(s)){h^=c.charCodeAt(0);h=Math.imul(h,16777619);}return h>>>0;}
function mulberry32(a){return function(){let t=a+=0x6D2B79F5;t=Math.imul(t^t>>>15,t|1);t^=t+Math.imul(t^t>>>7,t|61);return((t^t>>>14)>>>0)/4294967296;};}
function resourceTemplate(terrain,rng){const d=NS.TERRAIN[terrain],cap={};for(const k of ['food','wood','stone']){const [a,b]=d.cap[k];cap[k]=Math.floor(rng()*(b-a+1))+a;}let gold=0;if(terrain==='rock'&&rng()<.24)gold=Math.floor(rng()*66)+35;if(terrain==='mountain'&&rng()<.42)gold=Math.floor(rng()*111)+70;cap.gold=gold;return{cap,res:{food:cap.food*(.72+rng()*.26),wood:cap.wood*(.72+rng()*.26),stone:cap.stone*(.78+rng()*.20),gold:cap.gold*(.85+rng()*.15)}};}
function largestLand(map){const seen=new Uint8Array(map.tiles.length);let best=[];for(const t of map.tiles){if(seen[t.id]||!NS.TERRAIN[t.terrain].passable)continue;const q=[t.id],comp=[];seen[t.id]=1;for(let qi=0;qi<q.length;qi++){const cur=map.get(q[qi]);comp.push(cur);for(const n of map.neighbors4(cur.id))if(!seen[n.id]&&NS.TERRAIN[n.terrain].passable){seen[n.id]=1;q.push(n.id);}}if(comp.length>best.length)best=comp;}return best;}
