function spawnSuitability(map,t){if(!t||!NS.TERRAIN[t.terrain]?.passable)return-999;if(!['plain','grass','forest'].includes(t.terrain))return-300;const near=tilesWithin(map,t,2),far=tilesWithin(map,t,3);let score=t.terrain==='plain'?44:t.terrain==='grass'?34:8;score+=NS.TERRAIN[t.terrain].regen.food*7;score+=near.reduce((s,q)=>s+NS.TERRAIN[q.terrain].regen.food,0)*1.1;score+=near.some(q=>q.terrain==='forest')?18:0;score+=far.some(q=>q.terrain==='rock'||q.terrain==='mountain')?7:0;score+=map.neighbors4(t.id).filter(q=>NS.TERRAIN[q.terrain].passable).length*3;score-=map.neighbors4(t.id).filter(q=>q.terrain==='water').length*8;return score;}
function chooseSpawns(map,n=4,rng=Math.random){const land=largestLand(map),minD=Math.max(5,Math.floor(Math.min(map.width,map.height)/3));let pool=land.filter(t=>['plain','grass'].includes(t.terrain)&&spawnSuitability(map,t)>=100);if(pool.length<n)pool=land.filter(t=>['plain','grass','forest'].includes(t.terrain)&&spawnSuitability(map,t)>=75);if(pool.length<n)pool=land.filter(t=>['plain','grass','forest'].includes(t.terrain));const chosen=[];for(let i=0;i<n;i++){let candidates=pool.filter(t=>!chosen.some(c=>c.id===t.id)&&chosen.every(c=>map.distance(c.id,t.id)>=minD));if(!candidates.length)candidates=pool.filter(t=>!chosen.some(c=>c.id===t.id)&&chosen.every(c=>map.distance(c.id,t.id)>=Math.max(3,minD-2)));if(!candidates.length)candidates=pool.filter(t=>!chosen.some(c=>c.id===t.id));if(!candidates.length)break;candidates.sort((a,b)=>spawnSuitability(map,b)-spawnSuitability(map,a));const top=candidates.slice(0,Math.max(1,Math.min(8,Math.ceil(candidates.length*.18))));chosen.push(top[Math.floor(rng()*top.length)]);}return chosen;}
function naturalGenerate(map,seed){const w=map.width,h=map.height,rng=mulberry32(hashSeed(seed)),arr1=new Float32Array(w*h),arr2=new Float32Array(w*h),arr3=new Float32Array(w*h);for(let i=0;i<arr1.length;i++){arr1[i]=rng();arr2[i]=rng();arr3[i]=rng();}const smooth=a=>{for(let p=0;p<3;p++){const b=new Float32Array(a.length);for(let y=0;y<h;y++)for(let x=0;x<w;x++){let s=0,n=0;for(let yy=Math.max(0,y-1);yy<=Math.min(h-1,y+1);yy++)for(let xx=Math.max(0,x-1);xx<=Math.min(w-1,x+1);xx++){s+=a[yy*w+xx];n++;}b[y*w+x]=s/n;}a=b;}return a;};const height=smooth(arr1),wet=smooth(arr2),rough=smooth(arr3);map.tiles=[];for(let y=0;y<h;y++)for(let x=0;x<w;x++){const i=y*w+x,edge=Math.min(x,y,w-1-x,h-1-y);let terrain;if((edge<1&&rng()<.38)||rough[i]<.42)terrain='water';else if(rough[i]>.57)terrain=rough[i]>.625?'mountain':'rock';else if(wet[i]>.535)terrain='forest';else if(wet[i]>.485)terrain='grass';else terrain='plain';const t=new NS.Tile(i,x,y,terrain),r=resourceTemplate(terrain,rng);t.resourceCap=r.cap;t.resources=r.res;t.lastResourceDay=1;map.tiles.push(t);}map.ruinIds=new Set();map.generationSeed=seed;map.generationMode='natural';const sp=chooseSpawns(map,4,rng);map.spawnIds=sp.map(t=>t.id);return map;}
