function validateMapData(d){if(!d||d.format!==MAP_FORMAT||Number(d.version)!==MAP_VERSION)throw new Error('Village Observer MapData v1 파일이 아닙니다.');if(!Number.isInteger(d.width)||!Number.isInteger(d.height)||d.width<4||d.height<4||d.width>200||d.height>200)throw new Error('맵 크기는 4~200 범위여야 합니다.');if(!Array.isArray(d.tiles)||d.tiles.length!==d.width*d.height)throw new Error('타일 데이터 수가 맵 크기와 맞지 않습니다.');const seen=new Set();for(let i=0;i<d.tiles.length;i++){const t=d.tiles[i];if(!NS.TERRAIN[t?.terrain])throw new Error(`알 수 없는 지형: ${t?.terrain}`);for(const k of ['food','wood','stone','gold'])if(!Number.isFinite(Number(t.resourceCap?.[k]))||!Number.isFinite(Number(t.resources?.[k])))throw new Error(`타일 #${i}의 ${k} 자원 값이 유효하지 않습니다.`);}if(!Array.isArray(d.spawns)||d.spawns.length<4)throw new Error('현재 게임은 최소 4개의 Spawn이 필요합니다.');const warnings=[];for(let i=0;i<4;i++){const s=d.spawns[i];if(!Number.isFinite(s?.x)||!Number.isFinite(s?.y))throw new Error(`Spawn ${s?.id||i+1}의 위치가 없습니다.`);const x=Math.floor(s.x),y=Math.floor(s.y);if(x<0||y<0||x>=d.width||y>=d.height)throw new Error(`Spawn ${s.id||i+1}이 맵 바깥에 있습니다.`);const key=`${x},${y}`;if(seen.has(key))throw new Error('같은 타일에 Spawn을 두 개 이상 둘 수 없습니다.');seen.add(key);const src=d.tiles[y*d.width+x];if(!NS.TERRAIN[src.terrain].passable)throw new Error(`Spawn ${s.id||i+1}이 물 타일에 있습니다.`);}return warnings;}
function tileMapFromData(d){validateMapData(d);const m=Object.create(NS.TileMap.prototype);m.width=d.width;m.height=d.height;m.tiles=[];m.ruinIds=new Set();m.generationSeed=d.seed||'';m.generationMode='mapdata';m.mapName=d.name||'사용자 지도';for(let i=0;i<d.tiles.length;i++){const src=d.tiles[i],x=i%d.width,y=Math.floor(i/d.width),t=new NS.Tile(i,x,y,src.terrain);t.resourceCap={food:+src.resourceCap.food||0,wood:+src.resourceCap.wood||0,stone:+src.resourceCap.stone||0,gold:+src.resourceCap.gold||0};t.resources={food:clamp(+src.resources.food||0,0,t.resourceCap.food),wood:clamp(+src.resources.wood||0,0,t.resourceCap.wood),stone:clamp(+src.resources.stone||0,0,t.resourceCap.stone),gold:clamp(+src.resources.gold||0,0,t.resourceCap.gold)};t.lastResourceDay=1;t.ownerId=null;t.coreVillageId=null;t.ruin=null;t.buildings=[];t.unoccupiedDays=0;m.tiles.push(t);}m.spawnIds=d.spawns.slice(0,4).map(s=>Math.floor(s.y)*d.width+Math.floor(s.x));return m;}
