NS.World.prototype.createVillages=function(n){const names=[...NAMES].sort(()=>Math.random()-.5).slice(0,n);let chosen=(this.map.spawnIds||[]).slice(0,n).map(id=>this.map.get(id)).filter(Boolean);if(chosen.length<n)chosen=chooseSpawns(this.map,n,Math.random);if(chosen.length<n)throw new Error('국가를 배치할 수 있는 육지 Spawn이 부족합니다.');this.map.spawnIds=chosen.map(t=>t.id);for(let i=0;i<n;i++){const tile=chosen[i],v=new NS.Village(i,names[i],tile.id,NS.Brains.types[i%NS.Brains.types.length],this);this.villages.push(v);tile.ownerId=v.id;tile.coreVillageId=v.id;}for(const v of this.villages){NS.Relationships.initializeVillage(v);for(const o of this.villages)if(v.id!==o.id)v.relations[o.id]=rand(-15,25);v.recordHistory(this);}this.selectedVillageId=this.villages[0].id;this.selectedPersonId=this.villages[0].residents[0]?.id||null;this.selectedTileId=this.villages[0].coreTileId;this.log('세계가 시작되었습니다. 자연 지형과 생존 가능한 시작점을 바탕으로 주민들이 정착했습니다.',true,'WORLD_START',{mapMode:this.map.generationMode||'natural',seed:this.map.generationSeed||'',spawns:this.map.spawnIds});};

