NS.World.prototype.socialAndMigration=function(){for(const v of this.activeVillages){v.foodCrisisDays=Number(v.foodCrisisDays)||0;const fd=v.foodReserveDays();if(fd<7)v.foodCrisisDays++;else v.foodCrisisDays=Math.max(0,v.foodCrisisDays-2);if(v.foodCrisisDays<18)continue;const chance=clamp(.006+(v.foodCrisisDays-18)*.00035,.006,.022);if(Math.random()>=chance)continue;const movers=v.residents.filter(p=>p.alive&&p.age>=15&&p.assignment!=='PIONEER'),targets=this.activeVillages.filter(o=>o.id!==v.id&&o.foodReserveDays()>42);if(!movers.length||!targets.length)continue;const p=pick(movers),t=targets.sort((a,b)=>(v.relations[b.id]||0)-(v.relations[a.id]||0))[0];window.VSim?.V033I1?.returnEquipment?.(v,this,p,'EXTERNAL_MIGRATION');v.residents=v.residents.filter(x=>x.id!==p.id);p.villageId=t.id;p.homeTileId=t.coreTileId;t.residents.push(p);v.migrationStats.externalOut++;t.migrationStats.externalIn++;v.relations[t.id]=(v.relations[t.id]||0)+1;this.log(`${p.name}이(가) 장기적인 식량 부족을 피해 ${v.name}에서 ${t.name}(으)로 이주했습니다.`,true,'MIGRATION',{person:p.name,from:v.name,to:t.name,foodCrisisDays:v.foodCrisisDays});}};
