NS.TechSystem.available=function(v){return NS.TECH_ORDER.filter(id=>!v.technologies.has(id)&&NS.TECH[id].req.every(r=>v.technologies.has(r)));};
NS.TechSystem.choose=function(v,w){const ids=this.available(v);if(!ids.length)return null;const rr=v.resourceRatios(w),fd=v.foodReserveDays(),trade=v.tradePressure(w),pop=v.population(),sett=v.territory.size,buildings=type=>v.buildingCount?.(w,type)||0;const score=id=>{let s=13-Math.min(7,NS.TECH[id].cost/230);if(['AGRICULTURE','IRRIGATION','GRANARY','CROP_ROTATION','FOOD_PRESERVATION'].includes(id))s+=Math.max(0,55-fd)*.32+Math.max(0,.35-rr.food)*40;if(['CARPENTRY','FORESTRY','ARCHITECTURE'].includes(id))s+=Math.max(0,.38-rr.wood)*34+sett*1.2;if(['MASONRY','QUARRY','ENGINEERING','FORTIFICATION'].includes(id))s+=Math.max(0,.30-rr.stone)*28+sett;if(['BARTER','CART','MARKET','ROADS','CURRENCY','STANDARD_WEIGHTS','LONG_DISTANCE_TRADE','COMMERCIAL_LAW','ENVOYS'].includes(id))s+=trade*19+(NS.AIProfileCompat(v,'tradeDiplomacy')>.5?10:0)+(v.tradeStats?.count||0)*.10;if(['RECORD_KEEPING','SCHOLARSHIP','ACADEMY','EDUCATION'].includes(id))s+=pop*.20+6;if(['SURVEYING','FRONTIER_LOGISTICS','ADMINISTRATION','WATCHTOWERS'].includes(id))s+=sett*3.5+(NS.AIProfileCompat(v,'territorialExpansion')>.5?7:0);if(['URBAN_PLANNING','SANITATION','URBANIZATION','PUBLIC_WORKS'].includes(id))s+=Math.max(0,pop-18)*.35+sett*1.8;if(id==='ACADEMY'&&buildings('schoolhouse')===0)s+=4;return s+Math.random()*2.5;};return ids.sort((a,b)=>score(b)-score(a))[0];};

const checkEurekas13=NS.Village.prototype.checkEurekas;
NS.Village.prototype.checkEurekas=function(w){checkEurekas13.call(this,w);const tiles=[...this.territory].map(id=>w.map.get(id)).filter(Boolean),buildings=type=>this.buildingCount?.(w,type)||tiles.reduce((s,t)=>s+t.buildings.filter(b=>b===type).length,0),contacts=NS.V013?.contactIds?.(this,w)||[];if(tiles.some(t=>t.terrain==='forest'))this.grantEureka('FORESTRY',w);if(buildings('granary')>=1)this.grantEureka('FOOD_PRESERVATION',w);if(contacts.length>0)this.grantEureka('ENVOYS',w);if(this.totalKnowledge>=500)this.grantEureka('ACADEMY',w);if(this.territory.size>=4)this.grantEureka('WATCHTOWERS',w);if(buildings('palisade')>=2)this.grantEureka('FORTIFICATION',w);if((this.tradeStats?.count||0)>=12)this.grantEureka('COMMERCIAL_LAW',w);if(tiles.reduce((s,t)=>s+t.buildings.length,0)>=12)this.grantEureka('PUBLIC_WORKS',w);};

