 NS.UI.prototype.renderTile=function(){renderTile13.call(this);const el=this.q('tileInspector');if(!el)return;el.querySelectorAll('.stock > span:last-child').forEach(x=>{const m=x.textContent.match(/^\s*([\d.]+)\/([\d.]+)\s*$/);if(m)x.textContent=`${Math.round(+m[1])}/${Math.round(+m[2])}`;});};
